mapper.update:
UPDATE collector_monitor_task SET
    next_run_at = CASE WHEN enabled = FALSE AND #{enabled} = TRUE THEN NOW() ELSE next_run_at END,
    consecutive_failures = CASE WHEN enabled = FALSE AND #{enabled} = TRUE THEN 0 ELSE consecutive_failures END,
    interval_minutes = #{intervalMinutes}, max_pages = #{maxPages}, enabled = #{enabled}, updated_by = #{actor}
WHERE id = #{id}

mapper.select:
SELECT id, task_id, status, error_code, created_records, updated_records, pages_fetched,
       possibly_truncated, started_at, finished_at
FROM collector_monitor_run WHERE task_id = #{id} ORDER BY id DESC LIMIT #{limit}
